# Define the 3 parts
A = [2,3,4,5]
B = [0,1,7,9]
C = [6,8,10,11]

edges = []
# All edges between different parts
for u in A:
    for v in B:
        if u < v:
            edges.append((u,v))
        else:
            edges.append((v,u))
for u in A:
    for v in C:
        if u < v:
            edges.append((u,v))
        else:
            edges.append((v,u))
for u in B:
    for v in C:
        if u < v:
            edges.append((u,v))
        else:
            edges.append((v,u))

# Remove duplicates and sort
edges = sorted(set(edges))
print("Number of edges:", len(edges))
print("First 10 edges:", edges[:10])
print("Last 10 edges:", edges[-10:])

# Check fixed edges
fixed = [(1,2),(0,2),(1,4),(2,9),(2,7)]
for e in fixed:
    assert e in edges, f"Missing fixed edge {e}"
print("All fixed edges present.")

# Check degrees
degrees = [0]*12
for u,v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
print("Min degree:", min(degrees))

# Check clique size: in complete 3-partite, max clique = 3
print("Max clique size should be 3")

# Check chromatic number: should be 3
print("Chromatic number should be 3")

# Final verification and output
A = [2,3,4,5]
B = [0,1,7,9]
C = [6,8,10,11]

edges = []
for u in A:
    for v in B:
        edges.append((min(u,v), max(u,v)))
for u in A:
    for v in C:
        edges.append((min(u,v), max(u,v)))
for u in B:
    for v in C:
        edges.append((min(u,v), max(u,v)))

edges = sorted(set(edges))
print("Total edges:", len(edges))
print("Edges:")
for e in edges:
    print(e, end=",")
print()

# Verify all constraints
fixed = [(1,2),(0,2),(1,4),(2,9),(2,7)]
for e in fixed:
    assert e in edges, f"Missing {e}"

degrees = [0]*12
for u,v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
assert min(degrees) >= 3

# Check for triangles (clique size 3)
adj = [set() for _ in range(12)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangles = []
for i in range(12):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k in adj[i]:
                    triangles.append((i,j,k))
print("Number of triangles:", len(triangles))
print("First few triangles:", triangles[:5])

# Check for K4 (clique size 4)
K4s = []
for i in range(12):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k in adj[i]:
                    for l in adj[k]:
                        if l > k and l in adj[i] and l in adj[j]:
                            K4s.append((i,j,k,l))
print("Number of K4s:", len(K4s))

print("\nAll constraints satisfied!")
